/* Reset routines */

void MOD_mkBF16_SIMD::reset_RST_N(tUInt8 ARG_rst_in)
{
  PORT_RST_N = ARG_rst_in;
  INST_out_fifo.reset_RST(ARG_rst_in);
  INST_mid_fifo.reset_RST(ARG_rst_in);
  INST_in_fifo.reset_RST(ARG_rst_in);
}


