/* Functions to set the elaborated clock id */

void MOD_mkBF16_SIMD::set_clk_0(char const *s)
{
  __clk_handle_0 = bk_get_or_define_clock(sim_hdl, s);
}


/* State dumping routine */
void MOD_mkBF16_SIMD::dump_state(unsigned int indent)
{
  printf("%*s%s:\n", indent, "", inst_name);
  INST_in_fifo.dump_state(indent + 2u);
  INST_mid_fifo.dump_state(indent + 2u);
  INST_out_fifo.dump_state(indent + 2u);
}


/* VCD dumping routines */

unsigned int MOD_mkBF16_SIMD::dump_VCD_defs(unsigned int levels)
{
  vcd_write_scope_start(sim_hdl, inst_name);
  vcd_num = vcd_reserve_ids(sim_hdl, 4u);
  unsigned int num = vcd_num;
  for (unsigned int clk = 0u; clk < bk_num_clocks(sim_hdl); ++clk)
    vcd_add_clock_def(sim_hdl, this, bk_clock_name(sim_hdl, clk), bk_clock_vcd_num(sim_hdl, clk));
  vcd_write_def(sim_hdl, bk_clock_vcd_num(sim_hdl, __clk_handle_0), "CLK", 1u);
  vcd_write_def(sim_hdl, num++, "RST_N", 1u);
  num = INST_in_fifo.dump_VCD_defs(num);
  num = INST_mid_fifo.dump_VCD_defs(num);
  num = INST_out_fifo.dump_VCD_defs(num);
  vcd_write_scope_end(sim_hdl);
  return num;
}

void MOD_mkBF16_SIMD::dump_VCD(tVCDDumpType dt, unsigned int levels, MOD_mkBF16_SIMD &backing)
{
  vcd_defs(dt, backing);
  vcd_prims(dt, backing);
}

void MOD_mkBF16_SIMD::vcd_defs(tVCDDumpType dt, MOD_mkBF16_SIMD &backing)
{
  unsigned int num = vcd_num;
  if (dt == VCD_DUMP_XS)
  {
    vcd_write_x(sim_hdl, num++, 1u);
  }
  else
    if (dt == VCD_DUMP_CHANGES)
    {
      if ((backing.PORT_RST_N) != PORT_RST_N)
      {
	vcd_write_val(sim_hdl, num, PORT_RST_N, 1u);
	backing.PORT_RST_N = PORT_RST_N;
      }
      ++num;
    }
    else
    {
      vcd_write_val(sim_hdl, num++, PORT_RST_N, 1u);
      backing.PORT_RST_N = PORT_RST_N;
    }
}

void MOD_mkBF16_SIMD::vcd_prims(tVCDDumpType dt, MOD_mkBF16_SIMD &backing)
{
  INST_in_fifo.dump_VCD(dt, backing.INST_in_fifo);
  INST_mid_fifo.dump_VCD(dt, backing.INST_mid_fifo);
  INST_out_fifo.dump_VCD(dt, backing.INST_out_fifo);
}
